-- =============================================-- Author:		<Jose Roman>-- Create date: <27-07-2018>-- Description:	<Se devuelve la cantidad total faltante del pedido para validar que se pueda cerrar>-- =============================================CREATE PROCEDURE MM_SP_CatidadTotalFaltantePorPedido		@IdPedido INT,	/*---------------------Parametros contrato---------------------*/	@IdContrato INT = NULL,	@IdUsuario INT = NULL,	@FechaRegistro DATETIME = NULL		/*---------------------Parametros 
contrato---------------------*/ASBEGIN	SELECT 		(SUM(pd.Cantidad) - SUM(ISNULL(apd.Cantidad, 0))) AS CantidadFaltanteAlCierre	FROM dbo.MM_Pedido p	INNER JOIN dbo.MM_PedidoDetalle pd ON pd.IdPedido = p.IdPedido	LEFT JOIN	MM_AceptacionPedido	AP		ON	p.IdPedido	=	AP.IdPedido		AND ISNULL(AP.IdEliminado,0)	=	0	LEFT JOIN dbo.MM_AceptacionPedidoDetalle apd 		ON apd.IdPedidoDetalle = pd.IdPedidoDetalle 		AND AP.IdAceptacionPedido	=	apd.IdAceptacionPedido	WHERE p.idpedido = @IdPedido		AND ISNULL(apd.IdEstatusEliminado, 0) = 0END